#[cfg(unix)]
#[test]
fn カレントディレクトリを指す要素は取り除かれる() {
    let dir = TempDir::new("canonical");
    fs::write(dir.join("document.dcmp"), "{}").expect("ファイルを用意できる");
    let raw = format!("{}/./document.dcmp", dir.path().display());

    assert_eq!(canonicalized(&raw), canonical_in(&dir, "document.dcmp"));
}

#[cfg(unix)]
#[test]
fn symlink経由の綴りは実体の綴りになる() {
    let dir = TempDir::new("canonical");
    fs::write(dir.join("real.dcmp"), "{}").expect("ファイルを用意できる");
    std::os::unix::fs::symlink(dir.join("real.dcmp"), dir.join("link.dcmp"))
        .expect("symlink を作れる");

    let canonical = canonicalized(&raw_document_path(&dir, "link.dcmp"));

    assert_eq!(canonical, canonical_in(&dir, "real.dcmp"));
}

#[cfg(unix)]
#[test]
fn 実体の拡張子がdcmpでないsymlinkは拒否される() {
    let dir = TempDir::new("canonical-edge");
    std::fs::write(dir.join("notes.txt"), "x").expect("ファイルを用意できる");
    std::os::unix::fs::symlink(dir.join("notes.txt"), dir.join("link.dcmp"))
        .expect("symlink を作れる");

    assert!(is_rejected(&raw_document_path(&dir, "link.dcmp")));
}

test("後から別の綴りで監視し直すと、前の綴りには外部変更が届かない", async () => {
  const fake = DocumentIpcFake.create({ [Path]: `{}` });
  fake.linkPath({ link: LinkPath, target: Path });
  const received: DocumentChanged[] = [];
  Result.unwrap(
    await fake.ipc.subscribeChanged((changed) => received.push(changed)),
  );
  Result.unwrap(await fake.ipc.watch(Path));
  Result.unwrap(await fake.ipc.watch(LinkPath));

  fake.changeExternally(Path, `{ "formatVersion": "1.0" }`);

  expect(received).toStrictEqual([
    { path: LinkPath, content: `{ "formatVersion": "1.0" }` },
  ]);
});

test("開いているファイルを別の綴りで落としても、タブは増えない", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home") },
    { open: DialogChoice.Canceled, save: DialogChoice.Canceled },
    { linkedPaths: [{ link: LinkPath, target: Path }] },
  );
  await observer.dropFiles([Path]);

  await observer.dropFiles([LinkPath]);

  expect(openedPaths(observer.session())).toStrictEqual([Path]);
});

test("綴りを寄せるのを拒まれたファイルを選ぶと、使えないパスとして失敗する", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home") },
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
    { canonicalizeDenials: [{ path: Path, kind: "invalidPath" }] },
  );

  await observer.openDocument();

  expect(DocumentSession.failure(observer.session())).toStrictEqual(
    Option.some({
      kind: "io",
      error: DocumentAccessFailure.create(
        DocumentAccessFailureReasons.UnusablePath,
        `${Path}: ドキュメントのパスとして扱えない`,
      ),
    }),
  );
});

test("保存された一覧のうち、同じファイルの別の綴りは 1 行にまとまる", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home"), [SecondPath]: artboardContent("shop") },
    NoDialogChoices,
    {
      storedAppState: storedRecentPaths([Path, LinkPath, SecondPath]),
      linkedPaths: [{ link: LinkPath, target: Path }],
    },
  );

  await observer.settle();

  expect(observer.recentPaths()).toStrictEqual([Path, SecondPath]);
});

/*
 * 別の綴りで開いた側が監視を張り直すと、前の綴りへは通知が届かなくなる（Rust は実体ごとに
 * 監視を 1 つだけ持つ）。綴りを寄せずにタブが 2 つになると、最初のタブが取り残される。
 */
test("開いているファイルを別の綴りで落としても、外部変更はそのタブに反映される", async () => {
  const observer = renderEditorScreen(
    { [Path]: artboardContent("home") },
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
  );
  observer.files.linkPath({ link: LinkPath, target: Path });
  await startOpen(observer);
  await observer.dropFiles([LinkPath]);

  await changeExternally(observer.files, Path, artboardContent("profile"));
  await selectTab(Path);

  expect(
    within(artboardList()).getByRole("button", { name: "profile" }),
  ).toBeDefined();
});

pub fn canonical_form(path: &Path) -> PathBuf {
    if let Ok(canonical) = path.canonicalize() {
        return without_verbatim_disk(canonical);
    }

    // ファイルがまだ存在しない場合は canonicalize できない。新規ファイルへの
    // `record_write` は書き込み前に記録するのでここを通り、書き込み後の問い合わせは
    // 上の分岐を通る。両者が同じキーになるよう、親ディレクトリだけを正規化して組み立てる。
    let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) else {
        return path.to_path_buf();
    };
    let parent = if parent.as_os_str().is_empty() {
        Path::new(".")
    } else {
        parent
    };
    match parent.canonicalize() {
        Ok(directory) => without_verbatim_disk(directory).join(file_name),
        Err(_) => path.to_path_buf(),
    }
}

fn without_verbatim_disk(path: PathBuf) -> PathBuf {
    let mut components = path.components();
    let Some(Component::Prefix(prefix)) = components.next() else {
        return path;
    };
    let Prefix::VerbatimDisk(drive) = prefix.kind() else {
        return path;
    };
    let rest: PathBuf = components.collect();
    PathBuf::from(format!("{}:", char::from(drive))).join(rest)
}

// 起動時の復元は最近使ったファイルの全行を寄せる。同期コマンドはメインスレッドで動き、
// 応答しないネットワークドライブの realpath で UI が固まりうるので、async で別スレッドへ出す。
#[tauri::command(async)]
pub fn canonicalize_document_path(path: String) -> Result<String, DocumentIoError> {
    canonicalize_requested(&path).map(|canonical| canonical.to_string_lossy().into_owned())
}

async function canonicalizeRecentPaths(
  ipc: DocumentIpc,
  paths: readonly FilePath[],
): Promise<readonly FilePath[]> {
  return Promise.all(
    paths.map(async (path) =>
      Result.unwrapOr(await ipc.canonicalize(path), path),
    ),
  );
}

async function loadDocument(
  ipc: DocumentIpc,
  path: FilePath,
): Promise<Result<OpenedDocument, DocumentOpenFailure>> {
  const canonical = await ipc.canonicalize(path);
  if (!Result.isOk(canonical)) {
    return Result.err(accessFailed(canonical.error));
  }
  const loaded = await ipc.load(canonical.value);
  if (!Result.isOk(loaded)) {
    return Result.err(accessFailed(loaded.error));
  }
  const opened = OpenedDocument.fromParsed(
    canonical.value,
    DocumentJson.parse(loaded.value),
  );
  return Result.isOk(opened)
    ? Result.ok(opened.value)
    : Result.err({ kind: "unparsable", errors: opened.error });
}

const linkTargets = new Map<string, string>();
const canonicalizeDenials = new Map<string, CanonicalizeDenialKind>();
// 実体から、監視を張ったときの綴りへの表。通知はその綴りで届き、別の綴りで張り直すと
// 置き換わる（Rust の `watch/watchers.rs` が実体ごとに監視を 1 つだけ持つのと同じ）。
const watchedSpellings = new Map<string, string>();
const listeners = new Set<(payload: unknown) => void>();
let subscribeDenied = false;

const targetOf = (path: string): string => linkTargets.get(path) ?? path;

const notifyChange = (target: string, content: string): void => {
  const path = watchedSpellings.get(target);
  if (path === undefined) {
    return;
  }
  for (const listener of listeners) {
    listener({ path, content });
  }
};

const canonicalizeDocumentPath = (path: string): Promise<unknown> => {
  switch (canonicalizeDenials.get(path)) {
    case "invalidPath":
      return Promise.reject({
        kind: "invalidPath",
        message: `${path}: ドキュメントのパスとして扱えない`,
      });
    case "ipcFailed":
      return ipcFailure(`canonicalize_document_path: ${path} に届かない`);
    case undefined:
      return Promise.resolve(targetOf(path));
  }
};
